using System;
using System.IO;
using System.Linq;
using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;
using System.Windows;
using System.Windows.Controls;
internal sealed class NaturalReminder {internal string Title,Due,Time,Repeat;internal int Anchor;internal string Summary{get{return Title+" · "+Schedule.Day(Due).ToString("dd/MM/yyyy")+" à "+Time+(Repeat=="monthly"?" · chaque mois":Repeat=="weekly"?" · chaque semaine":Repeat=="daily"?" · chaque jour":"");}}}
internal static class NaturalReminders {
 static string Fold(string text){var b=new StringBuilder();foreach(char c in text.ToLowerInvariant().Normalize(NormalizationForm.FormD))if(CharUnicodeInfo.GetUnicodeCategory(c)!=UnicodeCategory.NonSpacingMark)b.Append(c);return b.ToString().Normalize(NormalizationForm.FormC);}
 internal static NaturalReminder Parse(string input,DateTime today){
  if(String.IsNullOrWhiteSpace(input)||input.Length>500)throw new InvalidDataException("Écrivez une tâche avec une date ou une répétition.");string title=input.Trim();string s=Fold(title);DateTime day=today.Date;string repeat="none",time="09:00";int anchor=0;bool found=false;
  var hour=Regex.Match(s,@"\s+a\s+(\d{1,2})(?:h(?:(\d{2}))?|:(\d{2}))\s*$");if(hour.Success){int h=Int32.Parse(hour.Groups[1].Value),m=hour.Groups[2].Success?Int32.Parse(hour.Groups[2].Value):hour.Groups[3].Success?Int32.Parse(hour.Groups[3].Value):0;if(h>23||m>59)throw new InvalidDataException("Heure invalide.");time=h.ToString("00")+":"+m.ToString("00");title=title.Substring(0,hour.Index).Trim();s=Fold(title);}
  var monthly=Regex.Match(s,@"\s+(?:le|chaque)\s+(\d{1,2})\s+(?:de\s+)?chaque\s+mois\s*$");if(monthly.Success){anchor=Int32.Parse(monthly.Groups[1].Value);if(anchor<1||anchor>31)throw new InvalidDataException("Le jour doit être compris entre 1 et 31.");day=new DateTime(today.Year,today.Month,Math.Min(anchor,DateTime.DaysInMonth(today.Year,today.Month)));if(day<today.Date){var next=today.AddMonths(1);day=new DateTime(next.Year,next.Month,Math.Min(anchor,DateTime.DaysInMonth(next.Year,next.Month)));}repeat="monthly";found=true;title=title.Substring(0,monthly.Index).Trim();}
  else {var daily=Regex.Match(s,@"\s+(?:chaque jour|tous les jours|chaque semaine)\s*$");if(daily.Success){repeat=daily.Value.Contains("semaine")?"weekly":"daily";found=true;title=title.Substring(0,daily.Index).Trim();}else{var weekday=Regex.Match(s,@"\s+(?:(chaque|tous les)\s+)?(lundi|mardi|mercredi|jeudi|vendredi|samedi|dimanche)(?:\s+prochain)?\s*$");if(weekday.Success){var names=new[]{"dimanche","lundi","mardi","mercredi","jeudi","vendredi","samedi"};int offset=(Array.IndexOf(names,weekday.Groups[2].Value)-(int)today.DayOfWeek+7)%7;if(offset==0&&weekday.Value.Contains("prochain"))offset=7;day=today.Date.AddDays(offset);repeat=weekday.Groups[1].Success?"weekly":"none";found=true;title=title.Substring(0,weekday.Index).Trim();}else{var relative=Regex.Match(s,@"\s+(aujourd'hui|aujourd’hui|demain|apres-demain|dans \d{1,3} jours?)\s*$");if(relative.Success){string v=relative.Groups[1].Value;int offset=v=="demain"?1:v=="apres-demain"?2:v.StartsWith("dans ")?Int32.Parse(Regex.Match(v,@"\d+").Value):0;day=today.Date.AddDays(offset);found=true;title=title.Substring(0,relative.Index).Trim();}else{var date=Regex.Match(s,@"\s+(?:le\s+)?(\d{1,2}/\d{1,2}(?:/\d{4})?)\s*$");if(date.Success){string text=date.Groups[1].Value;bool year=text.Count(c=>c=='/')==2;if(!DateTime.TryParseExact(text+(year?"":"/"+today.Year),new[]{"d/M/yyyy","dd/MM/yyyy","d/MM/yyyy","dd/M/yyyy"},CultureInfo.InvariantCulture,DateTimeStyles.None,out day))throw new InvalidDataException("Cette date n’existe pas.");if(!year&&day<today.Date)day=day.AddYears(1);found=true;title=title.Substring(0,date.Index).Trim();}}}}}
  if(!found)throw new InvalidDataException("Date non reconnue. Essayez « demain à 14h », « chaque lundi » ou « le 5 de chaque mois ».");if(String.IsNullOrWhiteSpace(title)||title.Length>180)throw new InvalidDataException("Ajoutez un titre de 1 à 180 caractères avant la date.");return new NaturalReminder{Title=title,Due=day.ToString("yyyy-MM-dd"),Time=time,Repeat=repeat,Anchor=anchor==0?day.Day:anchor};
 }
 internal static WorkTask Add(Store store,NaturalReminder draft,string project){var task=new WorkTask{id=Guid.NewGuid().ToString(),title=draft.Title,project=project,status="todo",priority="Normale",due=draft.Due,dueTime=draft.Time,repeat=draft.Repeat,repeatDay=draft.Anchor,remindMinutes=0};PersonalWorkflows.Change(store,()=>store.Value.tasks.Add(task));return task;}
}
internal sealed partial class ModernWorkspace {
 void NaturalReminderDialog(){StackPanel body,actions;var w=Dialog("Créer un rappel en une phrase",out body,out actions,570);var input=new TextBox{MaxLength=500,Text=""};Field(body,"Que voulez-vous prévoir ?",input);body.Children.Add(T("Exemples : payer le loyer le 5 de chaque mois · appeler demain à 14h30 · sport chaque lundi à 18h",12,Muted,new Thickness(0,0,0,18)));var project=Combo(owner.AllProjects(),owner.AllProjects().First());Field(body,"Projet",project);var preview=T("",14,Ink,new Thickness(0,10,0,18));body.Children.Add(preview);body.Children.Add(T("Le rappel est créé à l’heure indiquée, à 09:00 par défaut. Vérifiez la prévisualisation avant d’ajouter.",11,Muted));NaturalReminder draft=null;bool accepted=false;Action parse=delegate{try{draft=NaturalReminders.Parse(input.Text,DateTime.Today);preview.Text=draft.Summary;}catch(Exception ex){draft=null;preview.Text=ex.Message;}};input.TextChanged+=delegate{parse();};parse();actions.Children.Add(Btn("Annuler",delegate{w.Close();},false,true));actions.Children.Add(Btn("Créer le rappel",delegate{if(accepted)return;parse();if(draft==null)return;try{NaturalReminders.Add(store,draft,Convert.ToString(project.SelectedItem));accepted=true;FinishFinanceDialog(w);}catch(Exception ex){preview.Text=ex.Message;}},true));ShowWindow(w);Refresh();}
}
